def f2(g):
    from collections import Counter
    n=len(g)//3
    res=[]
    for i in range(n):
        row=[]
        for j in range(n):
            vals=[g[a*n+i][b*n+j] for a in range(3) for b in range(3)]
            c=Counter(v for v in vals if v!=5)
            row.append(c.most_common(1)[0][0] if c else 5)
        res.append(row)
    return res
